Use `governor::RateLimiter` with `Quota::per_second` and a direct (single-key) limiter.

```rust
use governor::{Quota, RateLimiter};
use governor::clock::DefaultClock;
use governor::state::{InMemoryState, NotKeyed};
use std::num::NonZeroU32;
use std::sync::Arc;

pub type DirectLimiter = Arc<RateLimiter<NotKeyed, InMemoryState, DefaultClock>>;

pub fn build_limiter(rps: u32, burst: u32) -> DirectLimiter {
    let quota = Quota::per_second(NonZeroU32::new(rps).expect("rps>0"))
        .allow_burst(NonZeroU32::new(burst).expect("burst>0"));
    Arc::new(RateLimiter::direct(quota))
}

pub async fn await_permit(lim: &DirectLimiter) {
