Use `nom::number::complete::{be_u8, be_u16}` with `take` for the value.

```rust
use nom::{IResult, bytes::complete::take, number::complete::{be_u16, be_u8}};

#[derive(Debug, PartialEq)]
pub struct Tlv<'a> { pub tag: u8, pub value: &'a [u8] }

pub fn parse_tlv(input: &[u8]) -> IResult<&[u8], Tlv<'_>> {
    let (input, tag) = be_u8(input)?;
    let (input, len) = be_u16(input)?;
    let (input, value) = take(len as usize)(input)?;
    Ok((input, Tlv { tag, value }))
}

pub fn parse_all(mut input: &[u8]) -> Result<Vec<Tlv<'_>>, nom::Err<nom::error::Error<&[u8]>>> {
    let mut out = Vec::new();
    while !input.is_empty() {
        let (rest, tlv) = parse_tlv(input)?;
        out.push(tlv);
        input = rest;
    }
    Ok(out)
}
```

Configure a custom thread pool and submit jobs via `install`.

```rust
use rayon::ThreadPoolBuilder;
use std::sync::Arc;

pub struct ParallelEngine { pool: Arc<rayon::ThreadPool> }

impl ParallelEngine {
    pub fn build(threads: usize) -> Result<Self, rayon::ThreadPoolBuildError> {
        let pool = ThreadPoolBuilder::new()
            .num_threads(threads)
            .thread_name(|i| format!("par-engine-{i}"))
            .build()?;
        Ok(Self { pool: Arc::new(pool) })
    }
    pub fn map_reduce<I, T, M, R>(&self, items: Vec<I>, map: M, init: T, reduce: R) -> T
    where I: Send, T: Send + Clone, M: Fn(I) -> T + Sync + Send, R: Fn(T, T) -> T + Sync + Send {
        use rayon::prelude::*;
        self.pool.install(|| items.into_par_iter().map(map).reduce(|| init.clone(), reduce))
    }
}
```

