Pre-allocate chunks; maintain a free list of slot indices.

```rust
use std::mem::MaybeUninit;

pub struct FixedSlab<T> {
    storage: Vec<MaybeUninit<T>>,
    free: Vec<usize>,
    in_use: Vec<bool>,
}

impl<T> FixedSlab<T> {
    pub fn with_capacity(n: usize) -> Self {
        let mut storage = Vec::with_capacity(n);
        for _ in 0..n { storage.push(MaybeUninit::uninit()); }
        Self { storage, free: (0..n).rev().collect(), in_use: vec![false; n] }
    }
    pub fn alloc(&mut self, val: T) -> Option<usize> {
        let idx = self.free.pop()?;
        self.storage[idx].write(val);
        self.in_use[idx] = true;
        Some(idx)
    }
    pub fn free(&mut self, idx: usize) {
        if !self.in_use[idx] { return; }
        unsafe { self.storage[idx].assume_init_drop(); }
        self.in_use[idx] = false;
        self.free.push(idx);
    }
    pub fn get(&self, idx: usize) -> Option<&T> {
        if !self.in_use[idx] { return None; }
        Some(unsafe { self.storage[idx].assume_init_ref() })
    }
}

impl<T> Drop for FixedSlab<T> {
    fn drop(&mut self) {
        for (i, used) in self.in_use.iter().enumerate() {
            if *used { unsafe { self.storage[i].assume_init_drop(); } }
        }
    }
}
```

Use `TokioAsyncResolver` and wrap `lookup_ip` in `tokio::time::timeout`.

```rust
use hickory_resolver::TokioAsyncResolver;
use hickory_resolver::config::{ResolverConfig, ResolverOpts};
use std::net::IpAddr;
use std::time::Duration;
use tokio::time::timeout;

pub struct DeadlineResolver { inner: TokioAsyncResolver, deadline: Duration }

impl DeadlineResolver {
    pub fn new(deadline: Duration) -> Self {
        let inner = TokioAsyncResolver::tokio(ResolverConfig::default(), ResolverOpts::default());
        Self { inner, deadline }
    }
    pub async fn resolve(&self, host: &str) -> Result<Vec<IpAddr>, String> {
        let lookup = timeout(self.deadline, self.inner.lookup_ip(host))
