Bind a UDS path, `accept` in a loop, spawn per-connection handlers.

```rust
use std::path::PathBuf;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{UnixListener, UnixStream};

pub async fn run_uds_echo(path: PathBuf) -> std::io::Result<()> {
    let _ = std::fs::remove_file(&path);
    let listener = UnixListener::bind(&path)?;
    loop {
        let (sock, _addr) = listener.accept().await?;
        tokio::spawn(handle_uds_client(sock));
    }
}

async fn handle_uds_client(mut sock: UnixStream) {
    let mut buf = vec![0u8; 4096];
    loop {
        match sock.read(&mut buf).await {
            Ok(0) => return,
            Ok(n) => { if sock.write_all(&buf[..n]).await.is_err() { return; } }
            Err(_) => return,
        }
    }
}
```

