use mio::net::TcpListener;
use mio::{Events, Interest, Poll, Token};
use std::time::Duration;

const SERVER_TOKEN: Token = Token(0);

pub fn run_mio_reactor(addr: &str) -> std::io::Result<()> {
    let mut poll = Poll::new()?;
    let mut events = Events::with_capacity(128);
    let mut listener = TcpListener::bind(addr.parse().unwrap())?;
    poll.registry().register(&mut listener, SERVER_TOKEN, Interest::READABLE)?;
    loop {
        poll.poll(&mut events, Some(Duration::from_secs(5)))?;
        for ev in events.iter() {
            if ev.token() == SERVER_TOKEN && ev.is_readable() {
                while let Ok((_sock, addr)) = listener.accept() {
                    eprintln!("accepted {addr}");
                }
            }
        }
    }
}
