Use a thread-local batch + global atomic flush.

```rust
use std::cell::Cell;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

pub struct BatchedCounter { global: Arc<AtomicU64> }

thread_local! { static LOCAL: Cell<u64> = const { Cell::new(0) }; }
const FLUSH_AT: u64 = 1024;

impl BatchedCounter {
    pub fn new() -> Self { Self { global: Arc::new(AtomicU64::new(0)) } }
    pub fn bump(&self) {
        let next = LOCAL.with(|c| { let v = c.get() + 1; c.set(v); v });
        if next >= FLUSH_AT {
            self.global.fetch_add(next, Ordering::Relaxed);
            LOCAL.with(|c| c.set(0));
        }
    }
    pub fn snapshot(&self) -> u64 { self.global.load(Ordering::Relaxed) }
}

impl Clone for BatchedCounter { fn clone(&self) -> Self { Self { global: self.global.clone() } } }
