Use multiple hash functions on the key to set bits.

```rust
use bitvec::prelude::*;
use std::hash::{BuildHasher, Hash, Hasher};
use std::collections::hash_map::RandomState;

pub struct BloomFilter { bits: BitVec, hashers: Vec<RandomState> }

impl BloomFilter {
    pub fn new(bit_size: usize, k: usize) -> Self {
        Self { bits: bitvec![0; bit_size], hashers: (0..k).map(|_| RandomState::new()).collect() }
    }
    fn idx<T: Hash>(&self, item: &T, rs: &RandomState) -> usize {
        let mut h = rs.build_hasher();
        item.hash(&mut h);
        (h.finish() as usize) % self.bits.len()
    }
    pub fn insert<T: Hash>(&mut self, item: &T) {
        for rs in &self.hashers { let i = self.idx(item, rs); self.bits.set(i, true); }
    }
    pub fn might_contain<T: Hash>(&self, item: &T) -> bool {
        self.hashers.iter().all(|rs| self.bits[self.idx(item, rs)])
    }
}
