Track frequency per key and evict the lowest.

```rust
use priority_queue::PriorityQueue;
use std::cmp::Reverse;
use std::collections::HashMap;
use std::hash::Hash;

pub struct LfuCache<K: Hash + Eq + Clone, V: Clone> {
    data: HashMap<K, V>,
    freq: PriorityQueue<K, Reverse<u64>>,
    cap: usize,
}

impl<K: Hash + Eq + Clone, V: Clone> LfuCache<K, V> {
    pub fn new(cap: usize) -> Self {
        Self { data: HashMap::with_capacity(cap), freq: PriorityQueue::new(), cap }
    }
    pub fn lookup(&mut self, k: &K) -> Option<V> {
        let v = self.data.get(k)?.clone();
        self.freq.change_priority_by(k, |Reverse(c)| *c += 1);
        Some(v)
    }
    pub fn admit(&mut self, k: K, v: V) {
        if self.data.contains_key(&k) {
            self.data.insert(k.clone(), v);
            self.freq.change_priority_by(&k, |Reverse(c)| *c += 1);
            return;
        }
        if self.data.len() >= self.cap {
            if let Some((evict_k, _)) = self.freq.pop() { self.data.remove(&evict_k); }
        }
        self.data.insert(k.clone(), v);
        self.freq.push(k, Reverse(1));
    }
}
```

