pub fn batched_uring_reads(paths: Vec<PathBuf>) -> io::Result<Vec<Vec<u8>>> {
    tokio_uring::start(async move {
        let mut futures = Vec::with_capacity(paths.len());
        for p in &paths {
            let p = p.clone();
