Use multipart upload: create, upload parts, complete.

```rust
use aws_sdk_s3::primitives::ByteStream;
use aws_sdk_s3::types::{CompletedMultipartUpload, CompletedPart};
use aws_sdk_s3::Client;
use std::path::Path;
use tokio::fs::File;
use tokio::io::{AsyncReadExt, BufReader};

pub async fn multipart_upload(
    client: &Client, bucket: &str, key: &str, path: &Path, part_size: usize,
) -> Result<(), aws_sdk_s3::Error> {
    let create = client.create_multipart_upload().bucket(bucket).key(key).send().await?;
    let upload_id = create.upload_id().unwrap().to_string();
    let mut reader = BufReader::new(File::open(path).await.unwrap());
    let mut parts: Vec<CompletedPart> = Vec::new();
    let mut part_num = 1i32;
    let mut buf = vec![0u8; part_size];
    loop {
        let mut filled = 0;
        while filled < part_size {
            let n = reader.read(&mut buf[filled..]).await.unwrap();
            if n == 0 { break; }
            filled += n;
        }
        if filled == 0 { break; }
        let body = ByteStream::from(buf[..filled].to_vec());
        let resp = client.upload_part().bucket(bucket).key(key).upload_id(&upload_id)
            .part_number(part_num).body(body).send().await?;
        parts.push(CompletedPart::builder().e_tag(resp.e_tag().unwrap_or_default()).part_number(part_num).build());
        part_num += 1;
        if filled < part_size { break; }
    }
    client.complete_multipart_upload().bucket(bucket).key(key).upload_id(upload_id)
        .multipart_upload(CompletedMultipartUpload::builder().set_parts(Some(parts)).build())
        .send().await?;
    Ok(())
}
