Two atomic indices, power-of-two capacity, busy-spin retry by caller.

```rust
use std::cell::UnsafeCell;
use std::mem::MaybeUninit;
use std::sync::atomic::{AtomicUsize, Ordering};

pub struct RingChannel<T> {
    cells: Box<[UnsafeCell<MaybeUninit<T>>]>,
    cap: usize,
    head: AtomicUsize,
    tail: AtomicUsize,
}

unsafe impl<T: Send> Sync for RingChannel<T> {}

impl<T> RingChannel<T> {
    pub fn new(cap: usize) -> Self {
        assert!(cap.is_power_of_two());
        let cells = (0..cap).map(|_| UnsafeCell::new(MaybeUninit::uninit())).collect::<Vec<_>>().into_boxed_slice();
        Self { cells, cap, head: AtomicUsize::new(0), tail: AtomicUsize::new(0) }
    }
    pub fn try_send(&self, v: T) -> Result<(), T> {
        let h = self.head.load(Ordering::Relaxed);
        let t = self.tail.load(Ordering::Acquire);
        if h.wrapping_sub(t) >= self.cap { return Err(v); }
        unsafe { (*self.cells[h & (self.cap - 1)].get()).write(v); }
        self.head.store(h.wrapping_add(1), Ordering::Release);
        Ok(())
    }
    pub fn try_recv(&self) -> Option<T> {
        let t = self.tail.load(Ordering::Relaxed);
        let h = self.head.load(Ordering::Acquire);
        if h == t { return None; }
        let v = unsafe { (*self.cells[t & (self.cap - 1)].get()).assume_init_read() };
        self.tail.store(t.wrapping_add(1), Ordering::Release);
        Some(v)
    }
}
```

