```rust
use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::Packet;

pub fn sniff_tcp_meta(iface: NetworkInterface) -> std::io::Result<()> {
    let (_, mut rx) = match datalink::channel(&iface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => return Err(std::io::Error::new(std::io::ErrorKind::Other, "unsupported chan")),
        Err(e) => return Err(e),
    };
    loop {
        let frame = rx.next()?;
        let eth = match EthernetPacket::new(frame) { Some(e) => e, None => continue };
        if eth.get_ethertype() != EtherTypes::Ipv4 { continue; }
        let ip = match Ipv4Packet::new(eth.payload()) { Some(i) => i, None => continue };
        let tcp = match TcpPacket::new(ip.payload()) { Some(t) => t, None => continue };
        println!("{}:{} -> {}:{}", ip.get_source(), tcp.get_source(), ip.get_destination(), tcp.get_destination());
    }
}
