Track running EMA with smoothing factor alpha.

```rust
pub struct ExpMovingAvg { alpha: f64, value: Option<f64> }

impl ExpMovingAvg {
    pub fn new(alpha: f64) -> Self {
        assert!((0.0..=1.0).contains(&alpha));
        Self { alpha, value: None }
    }
    pub fn observe(&mut self, x: f64) -> f64 {
        let next = match self.value { None => x, Some(v) => self.alpha * x + (1.0 - self.alpha) * v };
        self.value = Some(next);
        next
    }
    pub fn current(&self) -> Option<f64> { self.value }
}
