Wrap `value` in `parking_lot::Mutex<Option<f64>>` if updates are infrequent; for very hot paths use an `AtomicU64` storing `f64::to_bits` and CAS-update:

```rust
use std::sync::atomic::{AtomicU64, Ordering};
pub struct AtomicEma { alpha: f64, bits: AtomicU64 }
impl AtomicEma {
    pub fn observe(&self, x: f64) {
        let alpha = self.alpha;
        let mut cur = self.bits.load(Ordering::Relaxed);
        loop {
            let v = f64::from_bits(cur);
            let next = if v.is_nan() { x } else { alpha * x + (1.0 - alpha) * v };
            match self.bits.compare_exchange_weak(cur, next.to_bits(), Ordering::AcqRel, Ordering::Relaxed) {
                Ok(_) => return, Err(seen) => cur = seen,
            }
        }
    }
}
