Wrap an inner writer; track elapsed since last flush.

```rust
use std::io::{self, Write};
use std::time::{Duration, Instant};

pub struct TimedBufWriter<W: Write> {
    inner: W,
    buf: Vec<u8>,
    cap: usize,
    deadline: Duration,
    last_flush: Instant,
}

impl<W: Write> TimedBufWriter<W> {
    pub fn new(inner: W, cap: usize, deadline: Duration) -> Self {
        Self { inner, buf: Vec::with_capacity(cap), cap, deadline, last_flush: Instant::now() }
    }
    fn maybe_flush(&mut self) -> io::Result<()> {
        if self.buf.len() >= self.cap || self.last_flush.elapsed() >= self.deadline {
            self.inner.write_all(&self.buf)?;
            self.buf.clear();
            self.last_flush = Instant::now();
        }
        Ok(())
    }
}

impl<W: Write> Write for TimedBufWriter<W> {
    fn write(&mut self, b: &[u8]) -> io::Result<usize> {
        self.buf.extend_from_slice(b);
        self.maybe_flush()?;
        Ok(b.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        if !self.buf.is_empty() { self.inner.write_all(&self.buf)?; self.buf.clear(); }
        self.last_flush = Instant::now();
        self.inner.flush()
    }
}
