Atomic increment of bucket counters keyed by bound.

```rust
use std::sync::atomic::{AtomicU64, Ordering};

pub struct BucketHistogram { bounds: Vec<f64>, counts: Vec<AtomicU64>, sum_bits: AtomicU64, total: AtomicU64 }

impl BucketHistogram {
    pub fn with_bounds(bounds: Vec<f64>) -> Self {
        let counts = (0..=bounds.len()).map(|_| AtomicU64::new(0)).collect();
        Self { bounds, counts, sum_bits: AtomicU64::new(0), total: AtomicU64::new(0) }
    }
    pub fn observe(&self, value: f64) {
        let idx = self.bounds.iter().position(|b| value <= *b).unwrap_or(self.bounds.len());
        self.counts[idx].fetch_add(1, Ordering::Relaxed);
        self.total.fetch_add(1, Ordering::Relaxed);
        let mut cur = self.sum_bits.load(Ordering::Relaxed);
        loop {
            let next = (f64::from_bits(cur) + value).to_bits();
            match self.sum_bits.compare_exchange_weak(cur, next, Ordering::Relaxed, Ordering::Relaxed) {
                Ok(_) => break, Err(seen) => cur = seen,
            }
        }
    }
}
