use std::collections::HashMap;
use tokio::sync::Mutex;
use tokio_postgres::{Client, Error, Statement};

pub struct CachedClient { client: Client, cache: Mutex<HashMap<String, Statement>> }

impl CachedClient {
    pub fn wrap(client: Client) -> Self { Self { client, cache: Mutex::new(HashMap::new()) } }
    pub async fn prepared(&self, sql: &str) -> Result<Statement, Error> {
        if let Some(s) = self.cache.lock().await.get(sql) { return Ok(s.clone()); }
