Track failures; when threshold exceeded, fast-fail until cool-off.

```rust
use std::sync::atomic::{AtomicU64, AtomicU8, Ordering};
use std::time::{Duration, Instant};

pub struct AsyncBreaker { fails: AtomicU64, opened_at: AtomicU64, state: AtomicU8, threshold: u64, cool_off: Duration }
const CLOSED: u8 = 0; const OPEN: u8 = 1; const HALF: u8 = 2;

impl AsyncBreaker {
    pub fn new(threshold: u64, cool_off: Duration) -> Self {
        Self { fails: AtomicU64::new(0), opened_at: AtomicU64::new(0), state: AtomicU8::new(CLOSED), threshold, cool_off }
    }
    pub fn allow(&self) -> bool {
        match self.state.load(Ordering::Acquire) {
            CLOSED => true,
            OPEN => {
                let opened = self.opened_at.load(Ordering::Acquire);
                if Instant::now().elapsed_since_epoch_millis() >= opened + self.cool_off.as_millis() as u64 {
                    let _ = self.state.compare_exchange(OPEN, HALF, Ordering::AcqRel, Ordering::Acquire);
                    true
                } else { false }
            }
            HALF => true, _ => false,
        }
    }
    pub fn record_success(&self) {
        self.fails.store(0, Ordering::Relaxed);
        self.state.store(CLOSED, Ordering::Release);
    }
    pub fn record_failure(&self) {
        let f = self.fails.fetch_add(1, Ordering::Relaxed) + 1;
        if f >= self.threshold {
            self.opened_at.store(Instant::now().elapsed_since_epoch_millis(), Ordering::Release);
            self.state.store(OPEN, Ordering::Release);
        }
    }
}

trait InstantExt { fn elapsed_since_epoch_millis(&self) -> u64; }
impl InstantExt for Instant { fn elapsed_since_epoch_millis(&self) -> u64 { self.elapsed().as_millis() as u64 } }
