Spawn N workers reading from a buffered channel; close the channel to signal exit.

```go
package workpool

import (
    "context"
    "sync"
)

type Job func(ctx context.Context) error

type Pool struct {
    jobs chan Job
    wg   sync.WaitGroup
}

func NewBoundedPool(workers, queue int) *Pool {
    p := &Pool{jobs: make(chan Job, queue)}
    p.wg.Add(workers)
    for i := 0; i < workers; i++ {
        go p.run(context.Background())
    }
    return p
}

func (p *Pool) run(ctx context.Context) {
    defer p.wg.Done()
    for j := range p.jobs {
        _ = j(ctx)
    }
}

func (p *Pool) Submit(j Job) { p.jobs <- j }

func (p *Pool) StopAndWait() {
    close(p.jobs)
    p.wg.Wait()
}
