func NewCtxPool(ctx context.Context, workers, queue int) *Pool {
    p := &Pool{jobs: make(chan Job, queue)}
    p.wg.Add(workers)
    for i := 0; i < workers; i++ {
        go func() {
            defer p.wg.Done()
            for {
                select {
                case <-ctx.Done(): return
                case j, ok := <-p.jobs:
                    if !ok { return }
                    _ = j(ctx)
                }
