```go
package retry

import (
    "context"
    "math"
    "math/rand"
    "time"
)

type Policy struct { MaxAttempts int; BaseDelay, MaxDelay time.Duration }

func Run(ctx context.Context, p Policy, op func(context.Context) error) error {
    var lastErr error
    for i := 0; i < p.MaxAttempts; i++ {
        if err := op(ctx); err == nil { return nil } else { lastErr = err }
        d := time.Duration(float64(p.BaseDelay) * math.Pow(2, float64(i)))
        if d > p.MaxDelay { d = p.MaxDelay }
        d += time.Duration(rand.Int63n(int64(d) / 2))
        select {
        case <-ctx.Done(): return ctx.Err()
        case <-time.After(d):
        }
    }
    return lastErr
}
