Use `sync.Map` and a janitor goroutine for expiration.

```go
package ttlcache

import (
    "sync"
    "time"
)

type entry struct { value any; expiresAt time.Time }
type TTLStore struct { items sync.Map; ttl time.Duration; stop chan struct{}; once sync.Once }

func Start(ttl, sweep time.Duration) *TTLStore {
    s := &TTLStore{ttl: ttl, stop: make(chan struct{})}
    go func() {
        t := time.NewTicker(sweep); defer t.Stop()
        for {
            select {
            case <-s.stop: return
            case now := <-t.C: s.items.Range(func(k, v any) bool { if v.(entry).expiresAt.Before(now) { s.items.Delete(k) }; return true })
            }
        }
    }()
    return s
}
func (s *TTLStore) Put(k, v any) { s.items.Store(k, entry{v, time.Now().Add(s.ttl)}) }
func (s *TTLStore) Get(k any) (any, bool) {
    raw, ok := s.items.Load(k); if !ok { return nil, false }
    e := raw.(entry); if e.expiresAt.Before(time.Now()) { s.items.Delete(k); return nil, false }
    return e.value, true
}
func (s *TTLStore) Close() { s.once.Do(func() { close(s.stop) }) }
