```go
package lrugen

import "container/list"

type kv[K comparable, V any] struct{ k K; v V }
type LRU[K comparable, V any] struct {
    cap int
    ll *list.List
    idx map[K]*list.Element
}
func NewLRU[K comparable, V any](cap int) *LRU[K, V] {
    return &LRU[K, V]{cap: cap, ll: list.New(), idx: make(map[K]*list.Element, cap)}
}
func (l *LRU[K, V]) Lookup(k K) (V, bool) {
    var zero V
    if e, ok := l.idx[k]; ok { l.ll.MoveToFront(e); return e.Value.(kv[K, V]).v, true }
    return zero, false
}
func (l *LRU[K, V]) Insert(k K, v V) {
    if e, ok := l.idx[k]; ok { e.Value = kv[K, V]{k, v}; l.ll.MoveToFront(e); return }
    e := l.ll.PushFront(kv[K, V]{k, v})
    l.idx[k] = e
    if l.ll.Len() > l.cap {
        last := l.ll.Back(); if last != nil { l.ll.Remove(last); delete(l.idx, last.Value.(kv[K, V]).k) }
    }
}
