import "time"

type Leaky struct{ tokens chan struct{}; stop chan struct{} }

func StartLeaky(burst int, rate time.Duration) *Leaky {
    l := &Leaky{tokens: make(chan struct{}, burst), stop: make(chan struct{})}
    for i := 0; i < burst; i++ { l.tokens <- struct{}{} }
    go func() {
