Singly-linked free list inside the unused blocks themselves.

```c
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct freenode { struct freenode *next; } freenode_t;

typedef struct {
    void *arena;
    freenode_t *head;
    size_t block_size;
    size_t blocks;
} fixed_pool_t;

int fixed_pool_init(fixed_pool_t *p, size_t block_size, size_t blocks) {
    if (block_size < sizeof(freenode_t)) return -1;
    p->arena = malloc(block_size * blocks);
    if (!p->arena) return -1;
    p->block_size = block_size;
    p->blocks = blocks;
    p->head = NULL;
    for (size_t i = 0; i < blocks; ++i) {
        freenode_t *node = (freenode_t *)((uint8_t *)p->arena + i * block_size);
        node->next = p->head;
        p->head = node;
    }
    return 0;
}

void *fixed_pool_alloc(fixed_pool_t *p) {
    if (!p->head) return NULL;
    freenode_t *n = p->head;
    p->head = n->next;
    return n;
}

void fixed_pool_free(fixed_pool_t *p, void *ptr) {
    freenode_t *n = (freenode_t *)ptr;
    n->next = p->head;
    p->head = n;
}

void fixed_pool_destroy(fixed_pool_t *p) { free(p->arena); }
```

Use a sentinel byte at a known offset within each freed block:

```c
#define FREED_MAGIC 0xDEADBEEFUL

typedef struct freenode_dbg { struct freenode_dbg *next; uint32_t magic; } freenode_dbg_t;

void fixed_pool_free_checked(fixed_pool_t *p, void *ptr) {
    freenode_dbg_t *n = (freenode_dbg_t *)ptr;
    if (n->magic == FREED_MAGIC) abort(); /* double free */
    n->magic = FREED_MAGIC;
    n->next = (freenode_dbg_t *)p->head;
    p->head = (freenode_t *)n;
}
