Create an epoll fd; register listener; accept and add per-conn fd.

```c
#include <sys/epoll.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>

static int set_nonblock(int fd) {
    int fl = fcntl(fd, F_GETFL, 0);
    if (fl < 0) return -1;
    return fcntl(fd, F_SETFL, fl | O_NONBLOCK);
}

int run_epoll_echo(int port) {
    int ls = socket(AF_INET, SOCK_STREAM, 0);
    if (ls < 0) return -1;
    int yes = 1; setsockopt(ls, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_addr.s_addr = htonl(INADDR_ANY), .sin_port = htons(port)};
    if (bind(ls, (struct sockaddr *)&addr, sizeof(addr)) < 0) return -1;
    if (listen(ls, 64) < 0) return -1;
    set_nonblock(ls);
    int ep = epoll_create1(0);
    if (ep < 0) return -1;
    struct epoll_event ev = {.events = EPOLLIN, .data.fd = ls};
    epoll_ctl(ep, EPOLL_CTL_ADD, ls, &ev);
    struct epoll_event evs[64];
    char buf[4096];
    for (;;) {
        int n = epoll_wait(ep, evs, 64, -1);
        for (int i = 0; i < n; ++i) {
            int fd = evs[i].data.fd;
            if (fd == ls) {
                int cs = accept(ls, NULL, NULL);
                if (cs < 0) continue;
                set_nonblock(cs);
                struct epoll_event ce = {.events = EPOLLIN | EPOLLET, .data.fd = cs};
                epoll_ctl(ep, EPOLL_CTL_ADD, cs, &ce);
            } else {
                ssize_t r = read(fd, buf, sizeof(buf));
                if (r <= 0) { close(fd); continue; }
                ssize_t w = 0;
                while (w < r) {
                    ssize_t k = write(fd, buf + w, r - w);
                    if (k < 0) { if (errno == EAGAIN) break; close(fd); break; }
                    w += k;
                }
            }
        }
    }
}
```

