void ll_destroy(ll_t *l, void (*free_value)(void *)) {
    ll_node_t *cur = l->head;
    while (cur) {
        ll_node_t *next = cur->next;
        if (free_value) free_value(cur->value);
        free(cur);
        cur = next;
    }
    l->head = NULL; l->len = 0;
}

