Power-of-two size; FNV-1a hash; linear probe.

```c
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

typedef struct { const char *key; void *value; uint8_t state; } slot_t;
#define SLOT_EMPTY 0
#define SLOT_USED 1
#define SLOT_TOMBSTONE 2

typedef struct { slot_t *slots; size_t cap; size_t count; } htab_t;

static uint64_t fnv1a(const char *s) {
    uint64_t h = 0xcbf29ce484222325ULL;
    while (*s) { h ^= (uint8_t)*s++; h *= 0x100000001b3ULL; }
    return h;
}

int htab_init(htab_t *h, size_t cap) {
    if ((cap & (cap - 1)) != 0) return -1;
    h->slots = calloc(cap, sizeof(slot_t));
    if (!h->slots) return -1;
    h->cap = cap; h->count = 0;
    return 0;
}

int htab_put(htab_t *h, const char *key, void *value) {
    if (h->count * 2 >= h->cap) return -1; /* caller must resize */
    size_t mask = h->cap - 1;
    size_t i = fnv1a(key) & mask;
    while (h->slots[i].state == SLOT_USED && strcmp(h->slots[i].key, key) != 0) i = (i + 1) & mask;
    if (h->slots[i].state != SLOT_USED) h->count++;
    h->slots[i].key = key; h->slots[i].value = value; h->slots[i].state = SLOT_USED;
    return 0;
}

void *htab_get(const htab_t *h, const char *key) {
    size_t mask = h->cap - 1;
    size_t i = fnv1a(key) & mask;
    while (h->slots[i].state != SLOT_EMPTY) {
        if (h->slots[i].state == SLOT_USED && strcmp(h->slots[i].key, key) == 0) return h->slots[i].value;
        i = (i + 1) & mask;
    }
    return NULL;
}
