```go
package chanmap

import "sync"

type ChannelMap[K comparable, V any] struct {
    mu sync.Mutex
    chans map[K]chan V
}

func New[K comparable, V any]() *ChannelMap[K, V] { return &ChannelMap[K, V]{chans: make(map[K]chan V)} }

func (m *ChannelMap[K, V]) Subscribe(k K, buf int) <-chan V {
    m.mu.Lock(); defer m.mu.Unlock()
    ch := make(chan V, buf)
    m.chans[k] = ch
    return ch
}

func (m *ChannelMap[K, V]) Publish(k K, v V) bool {
    m.mu.Lock(); ch, ok := m.chans[k]; m.mu.Unlock()
    if !ok { return false }
    select { case ch <- v: return true; default: return false }
}

func (m *ChannelMap[K, V]) Unsubscribe(k K) {
    m.mu.Lock(); defer m.mu.Unlock()
    if ch, ok := m.chans[k]; ok { close(ch); delete(m.chans, k) }
}
```

There's a subtle race: between releasing the lock in Publish and sending on the channel, Unsubscribe could close the channel — sending on a closed channel panics. Hold the lock through the send (slower but safe), or use `select` with a default and recover from the panic (ugly). The cleanest fix is reference-counting:

```go
func (m *ChannelMap[K, V]) PublishSafe(k K, v V) bool {
    m.mu.Lock(); defer m.mu.Unlock()
    ch, ok := m.chans[k]
    if !ok { return false }
    select { case ch <- v: return true; default: return false }
}
```

Now Publish holds the lock through the send, preventing concurrent close.

