pub struct Matrix<const N: usize, const M: usize> { data: [[f64; M]; N] }

impl<const N: usize, const M: usize> Matrix<N, M> {
    pub fn zeroed() -> Self { Self { data: [[0.0; M]; N] } }
    pub fn at(&self, r: usize, c: usize) -> f64 { self.data[r][c] }
    pub fn set(&mut self, r: usize, c: usize, v: f64) { self.data[r][c] = v; }
    pub fn transpose(&self) -> Matrix<M, N> {
        let mut out = Matrix::<M, N>::zeroed();
        for r in 0..N { for c in 0..M { out.data[c][r] = self.data[r][c]; } }
        out
    }
}
