Drop timestamps older than window; cap by count.

```go
package slidingwindow

import (
    "container/list"
    "sync"
    "time"
)

type SlidingLimiter struct{ mu sync.Mutex; window time.Duration; max int; events *list.List }

func NewSliding(window time.Duration, max int) *SlidingLimiter {
    return &SlidingLimiter{window: window, max: max, events: list.New()}
}

func (s *SlidingLimiter) Allow() bool {
    s.mu.Lock(); defer s.mu.Unlock()
    now := time.Now()
    cutoff := now.Add(-s.window)
    for e := s.events.Front(); e != nil && e.Value.(time.Time).Before(cutoff); e = s.events.Front() {
        s.events.Remove(e)
    }
    if s.events.Len() >= s.max { return false }
    s.events.PushBack(now)
    return true
}
