Use `errgroup` or a custom goroutine + channel pattern; cancel siblings on first success:

```go
import "sync"

func FirstReachable(parent context.Context, addrs []string, timeout time.Duration) (string, error) {
    ctx, cancel := context.WithCancel(parent); defer cancel()
    type res struct{ addr string; err error }
    out := make(chan res, len(addrs))
    var wg sync.WaitGroup
    for _, a := range addrs {
        a := a; wg.Add(1)
        go func() { defer wg.Done(); out <- res{a, TcpReachable(ctx, a, timeout)} }()
    }
    go func() { wg.Wait(); close(out) }()
    var lastErr error
    for r := range out {
        if r.err == nil { return r.addr, nil }
        lastErr = r.err
    }
    return "", lastErr
}
```

This is essentially the Happy Eyeballs algorithm used for IPv4/IPv6 dual-stack.

