```go
package flushloop

import (
    "context"
    "sync"
    "time"
)

type PeriodicFlusher struct{ buf []byte; mu sync.Mutex; flush func([]byte) error; period time.Duration }

func NewPeriodicFlusher(period time.Duration, flush func([]byte) error) *PeriodicFlusher {
    return &PeriodicFlusher{period: period, flush: flush}
}

func (p *PeriodicFlusher) Append(b []byte) { p.mu.Lock(); p.buf = append(p.buf, b...); p.mu.Unlock() }

func (p *PeriodicFlusher) Run(ctx context.Context) error {
    t := time.NewTicker(p.period); defer t.Stop()
    for {
        select {
        case <-ctx.Done(): return p.flushNow()
        case <-t.C: if err := p.flushNow(); err != nil { return err }
        }
    }
}

func (p *PeriodicFlusher) flushNow() error {
    p.mu.Lock(); b := p.buf; p.buf = nil; p.mu.Unlock()
    if len(b) == 0 { return nil }
    return p.flush(b)
}
