```go
package connpool

import (
    "context"
    "net"
)

type Pool struct{ slots chan net.Conn; dial func(context.Context) (net.Conn, error) }

func New(size int, dial func(context.Context) (net.Conn, error)) *Pool {
    return &Pool{slots: make(chan net.Conn, size), dial: dial}
}

func (p *Pool) Acquire(ctx context.Context) (net.Conn, error) {
    select {
    case c := <-p.slots: return c, nil
    default:
    }
    select {
    case c := <-p.slots: return c, nil
    case <-ctx.Done(): return nil, ctx.Err()
    default:
        return p.dial(ctx)
    }
}

func (p *Pool) Release(c net.Conn) {
    select { case p.slots <- c: default: c.Close() }
}
