type Drainable struct{ jobs chan func(); wg sync.WaitGroup; closed chan struct{}; once sync.Once }

func StartDrainable(workers int) *Drainable {
    d := &Drainable{jobs: make(chan func(), workers*2), closed: make(chan struct{})}
