use tower::Service;
use uuid::Uuid;

pub struct RequestIdLayer<S> { inner: S, header: HeaderName }

impl<S> RequestIdLayer<S> {
    pub fn new(inner: S) -> Self { Self { inner, header: HeaderName::from_static("x-request-id") } }
