Compose a breaker + retry policy.

```rust
use reqwest::{Client, Response};
use std::sync::atomic::{AtomicU32, AtomicU64, Ordering};
use std::time::{Duration, Instant};

pub struct ProtectedClient {
    client: Client,
    breaker: AtomicU32, // 0=closed, 1=open
    open_until: AtomicU64,
    fail_threshold: u32,
    fail_count: AtomicU32,
}

impl ProtectedClient {
    pub fn new(client: Client, fail_threshold: u32) -> Self {
        Self { client, breaker: AtomicU32::new(0), open_until: AtomicU64::new(0), fail_threshold, fail_count: AtomicU32::new(0) }
    }
    pub async fn fetch(&self, url: &str) -> Result<Response, String> {
        if self.breaker.load(Ordering::Acquire) == 1 {
            let now = Instant::now().elapsed().as_millis() as u64;
            if now < self.open_until.load(Ordering::Acquire) { return Err("breaker open".into()); }
            self.breaker.store(0, Ordering::Release);
        }
        match self.client.get(url).send().await {
            Ok(r) if r.status().is_success() => { self.fail_count.store(0, Ordering::Relaxed); Ok(r) }
            Ok(r) => self.record_failure(format!("status {}", r.status())),
            Err(e) => self.record_failure(e.to_string()),
        }
    }
    fn record_failure(&self, msg: String) -> Result<Response, String> {
        let f = self.fail_count.fetch_add(1, Ordering::Relaxed) + 1;
        if f >= self.fail_threshold {
            let until = (Instant::now() + Duration::from_secs(30)).elapsed().as_millis() as u64;
            self.open_until.store(until, Ordering::Release);
            self.breaker.store(1, Ordering::Release);
        }
        Err(msg)
    }
}
