Compare-and-swap on a futex word; sleep via SYS_futex.

```c
#include <linux/futex.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <stdatomic.h>
#include <stdint.h>

typedef _Atomic uint32_t mini_mutex_t;
#define MM_UNLOCKED 0u
#define MM_LOCKED 1u
#define MM_CONTENDED 2u

static int futex_wait(mini_mutex_t *m, uint32_t expected) {
    return syscall(SYS_futex, m, FUTEX_WAIT_PRIVATE, expected, NULL, NULL, 0);
}
static int futex_wake(mini_mutex_t *m, int n) {
    return syscall(SYS_futex, m, FUTEX_WAKE_PRIVATE, n, NULL, NULL, 0);
}

void mini_mutex_lock(mini_mutex_t *m) {
    uint32_t expected = MM_UNLOCKED;
    if (atomic_compare_exchange_strong(m, &expected, MM_LOCKED)) return;
    do {
        if (expected == MM_CONTENDED || atomic_exchange(m, MM_CONTENDED) != MM_UNLOCKED) {
            futex_wait(m, MM_CONTENDED);
        }
        expected = MM_UNLOCKED;
    } while (!atomic_compare_exchange_strong(m, &expected, MM_CONTENDED));
}

void mini_mutex_unlock(mini_mutex_t *m) {
    if (atomic_fetch_sub(m, 1) != MM_LOCKED) {
        atomic_store(m, MM_UNLOCKED);
        futex_wake(m, 1);
    }
}
