```rust
use serde_json::{Map, Value};

pub fn flatten_json_paths(v: &Value) -> Vec<(String, Value)> {
    let mut out = Vec::new();
    walk_paths("", v, &mut out);
    out
}

fn walk_paths(prefix: &str, v: &Value, out: &mut Vec<(String, Value)>) {
    match v {
        Value::Object(m) => {
            for (k, child) in m { let key = if prefix.is_empty() { k.clone() } else { format!("{prefix}.{k}") }; walk_paths(&key, child, out); }
        }
        Value::Array(a) => {
            for (i, child) in a.iter().enumerate() { let key = format!("{prefix}[{i}]"); walk_paths(&key, child, out); }
        }
        leaf => out.push((prefix.to_string(), leaf.clone())),
    }
}
