Use mmap2 to grow the file; atomic offset for next append.

```rust
use memmap2::{MmapMut, MmapOptions};
use std::fs::OpenOptions;
use std::io;
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};

pub struct AppendLog { mmap: MmapMut, end: AtomicU64 }

impl AppendLog {
    pub fn open(path: &Path, max_bytes: u64) -> io::Result<Self> {
        let f = OpenOptions::new().create(true).read(true).write(true).open(path)?;
        f.set_len(max_bytes)?;
        let mmap = unsafe { MmapOptions::new().len(max_bytes as usize).map_mut(&f)? };
        Ok(Self { mmap, end: AtomicU64::new(0) })
    }
    pub fn append_record(&self, payload: &[u8]) -> io::Result<u64> {
        let need = (4 + payload.len()) as u64;
        let off = self.end.fetch_add(need, Ordering::SeqCst);
        if off + need > self.mmap.len() as u64 { return Err(io::Error::new(io::ErrorKind::OutOfMemory, "log full")); }
        let dst = unsafe { &mut *(self.mmap.as_ptr().add(off as usize) as *mut [u8] as *mut [u8]) };
        // SAFETY: we reserved the region atomically; no other thread writes here.
        let region = unsafe { std::slice::from_raw_parts_mut(self.mmap.as_ptr().add(off as usize) as *mut u8, need as usize) };
        region[..4].copy_from_slice(&(payload.len() as u32).to_le_bytes());
        region[4..].copy_from_slice(payload);
        Ok(off)
    }
}
