Read the file in chunks; upload via goroutines + sem.

```go
package chunkupload

import (
    "context"
    "io"
    "os"
    "sync"
)

type PartUploader func(ctx context.Context, partNum int, body []byte) error

func UploadInChunks(ctx context.Context, path string, chunkSize int, parallelism int, upload PartUploader) error {
    f, err := os.Open(path); if err != nil { return err }
    defer f.Close()
    sem := make(chan struct{}, parallelism)
    var wg sync.WaitGroup
    var firstErr error
    var errMu sync.Mutex
    partNum := 0
    for {
        partNum++
        buf := make([]byte, chunkSize)
        n, err := io.ReadFull(f, buf)
        if n > 0 {
            wg.Add(1); sem <- struct{}{}
            go func(num int, data []byte) {
                defer wg.Done(); defer func() { <-sem }()
                if e := upload(ctx, num, data); e != nil { errMu.Lock(); if firstErr == nil { firstErr = e }; errMu.Unlock() }
            }(partNum, buf[:n])
        }
        if err == io.EOF || err == io.ErrUnexpectedEOF { break }
        if err != nil { wg.Wait(); return err }
    }
    wg.Wait()
    return firstErr
}
