use parking_lot::Mutex;
use std::sync::Arc;
use std::time::Duration;

pub struct DeadlineLock<T> { inner: Arc<Mutex<T>>, deadline: Duration }

impl<T> DeadlineLock<T> {
    pub fn new(value: T, deadline: Duration) -> Self { Self { inner: Arc::new(Mutex::new(value)), deadline } }
    pub fn with<R>(&self, f: impl FnOnce(&mut T) -> R) -> Option<R> {
        let mut guard = self.inner.try_lock_for(self.deadline)?;
        Some(f(&mut *guard))
    }
}

