Wrap http.RoundTripper with metrics callbacks.

```go
package metricsclient

import (
    "net/http"
    "sync/atomic"
    "time"
)

type InstrumentedTransport struct{ inner http.RoundTripper; reqs, errs atomic.Int64; totalLatencyMs atomic.Int64 }

func NewInstrumented(inner http.RoundTripper) *InstrumentedTransport {
    if inner == nil { inner = http.DefaultTransport }
    return &InstrumentedTransport{inner: inner}
}

func (t *InstrumentedTransport) RoundTrip(r *http.Request) (*http.Response, error) {
    start := time.Now()
    t.reqs.Add(1)
    resp, err := t.inner.RoundTrip(r)
    t.totalLatencyMs.Add(time.Since(start).Milliseconds())
    if err != nil { t.errs.Add(1) }
    return resp, err
}

func (t *InstrumentedTransport) Snapshot() (reqs, errs, latencyMs int64) {
    return t.reqs.Load(), t.errs.Load(), t.totalLatencyMs.Load()
}
