Wrap with HashMap; check cache first.

```rust
use std::collections::HashMap;
use std::hash::Hash;
use parking_lot::Mutex;

pub struct Memoized<K, V, F> { cache: Mutex<HashMap<K, V>>, compute: F }

impl<K: Hash + Eq + Clone, V: Clone, F: Fn(&K) -> Result<V, String>> Memoized<K, V, F> {
    pub fn wrap(compute: F) -> Self { Self { cache: Mutex::new(HashMap::new()), compute } }
    pub fn lookup(&self, key: &K) -> Result<V, String> {
        if let Some(v) = self.cache.lock().get(key) { return Ok(v.clone()); }
        let v = (self.compute)(key)?;
        self.cache.lock().insert(key.clone(), v.clone());
        Ok(v)
    }
}
