Pre-allocate large block; bump current pointer.

```c
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    uint8_t *base;
    size_t cap;
    size_t used;
} arena_t;

int arena_init(arena_t *a, size_t cap) {
    a->base = (uint8_t *)malloc(cap);
    if (!a->base) return -1;
    a->cap = cap; a->used = 0; return 0;
}

void *arena_alloc(arena_t *a, size_t bytes, size_t align) {
    uintptr_t cur = (uintptr_t)(a->base + a->used);
    uintptr_t aligned = (cur + (align - 1)) & ~(align - 1);
    size_t pad = (size_t)(aligned - cur);
    if (a->used + pad + bytes > a->cap) return NULL;
    a->used += pad + bytes;
    return (void *)aligned;
}

void arena_reset(arena_t *a) { a->used = 0; }
void arena_destroy(arena_t *a) { free(a->base); a->base = NULL; }
