```c
#include <openssl/evp.h>
#include <string.h>

int compute_sha256(const unsigned char *in, size_t in_len, unsigned char out[32]) {
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!ctx) return -1;
    int rc = -1;
    if (EVP_DigestInit_ex(ctx, EVP_sha256(), NULL) != 1) goto done;
    if (EVP_DigestUpdate(ctx, in, in_len) != 1) goto done;
    unsigned int outlen = 0;
    if (EVP_DigestFinal_ex(ctx, out, &outlen) != 1) goto done;
    rc = (outlen == 32) ? 0 : -1;
done:
    EVP_MD_CTX_free(ctx);
    return rc;
}
