Use a slice with head/tail indices.

```go
package overwriting

import "sync"

type OverwritingRing[T any] struct{ mu sync.Mutex; buf []T; cap, head, count int }

func NewOverwritingRing[T any](cap int) *OverwritingRing[T] { return &OverwritingRing[T]{buf: make([]T, cap), cap: cap} }

func (r *OverwritingRing[T]) Push(v T) {
    r.mu.Lock(); defer r.mu.Unlock()
    pos := (r.head + r.count) % r.cap
    r.buf[pos] = v
    if r.count < r.cap { r.count++ } else { r.head = (r.head + 1) % r.cap }
}

func (r *OverwritingRing[T]) Snapshot() []T {
    r.mu.Lock(); defer r.mu.Unlock()
    out := make([]T, r.count)
    for i := 0; i < r.count; i++ { out[i] = r.buf[(r.head+i)%r.cap] }
    return out
}
