RAII pattern — set on construction, restore on drop.

```rust
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

pub struct ScopedFlag { flag: Arc<AtomicBool>, prev: bool }

impl ScopedFlag {
    pub fn enter(flag: Arc<AtomicBool>) -> Self {
        let prev = flag.swap(true, Ordering::AcqRel);
        Self { flag, prev }
    }
}

impl Drop for ScopedFlag {
    fn drop(&mut self) {
        self.flag.store(self.prev, Ordering::Release);
    }
