Implement UnmarshalJSON validating allowed values.

```go
package statusenum

import (
    "encoding/json"
    "fmt"
)

type Status int
const (
    StatusUnknown Status = iota
    StatusActive
    StatusSuspended
)

func (s *Status) UnmarshalJSON(b []byte) error {
    var raw string
    if err := json.Unmarshal(b, &raw); err != nil { return err }
    switch raw {
    case "active": *s = StatusActive
    case "suspended": *s = StatusSuspended
    default: return fmt.Errorf("unknown status %q", raw)
    }
    return nil
}

func (s Status) MarshalJSON() ([]byte, error) {
    var name string
    switch s {
    case StatusActive: name = "active"
    case StatusSuspended: name = "suspended"
    default: name = "unknown"
    }
    return json.Marshal(name)
}
