Build a `h2::server::handshake` future.

```rust
use bytes::Bytes;
use h2::server::{self, SendResponse};
use h2::RecvStream;
use http::{Response, StatusCode};
use tokio::net::TcpListener;

pub async fn run_h2_echo(addr: &str) -> std::io::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    loop {
        let (sock, _) = listener.accept().await?;
        tokio::spawn(async move {
            if let Ok(mut conn) = server::handshake(sock).await {
                while let Some(Ok((req, mut resp))) = conn.accept().await {
                    tokio::spawn(handle_h2_request(req.into_body(), resp));
                }
            }
        });
    }
}

async fn handle_h2_request(mut body: RecvStream, mut resp: SendResponse<Bytes>) {
    let response = Response::builder().status(StatusCode::OK).body(()).unwrap();
    let mut send = match resp.send_response(response, false) { Ok(s) => s, Err(_) => return };
    while let Some(Ok(chunk)) = body.data().await {
        let _ = send.send_data(chunk, false);
        let _ = body.flow_control().release_capacity(chunk.len());
    }
    let _ = send.send_data(Bytes::new(), true);
}
