Use a regex or manual scan.

```rust
use std::time::Duration;

pub fn parse_human_duration(s: &str) -> Result<Duration, String> {
    let mut total = Duration::ZERO;
    let mut digits = String::new();
    let mut iter = s.chars().peekable();
    while let Some(&c) = iter.peek() {
        if c.is_ascii_digit() { digits.push(c); iter.next(); }
        else {
            let n: u64 = digits.parse().map_err(|_| format!("bad number near {c}"))?;
            digits.clear();
            let mut unit = String::new();
            while let Some(&c2) = iter.peek() { if c2.is_ascii_alphabetic() { unit.push(c2); iter.next(); } else { break; } }
            total += match unit.as_str() {
                "ms" => Duration::from_millis(n),
                "s" => Duration::from_secs(n),
                "m" => Duration::from_secs(n * 60),
                "h" => Duration::from_secs(n * 3600),
                other => return Err(format!("unknown unit {other}")),
            };
        }
    }
    if !digits.is_empty() { return Err("trailing digits without unit".into()); }
    Ok(total)
}
