```go
package fswatch

import (
    "context"
    "github.com/fsnotify/fsnotify"
)

func WatchDir(ctx context.Context, dir string, onChange func(string)) error {
    w, err := fsnotify.NewWatcher(); if err != nil { return err }
    defer w.Close()
    if err := w.Add(dir); err != nil { return err }
    for {
        select {
        case <-ctx.Done(): return ctx.Err()
        case ev, ok := <-w.Events:
            if !ok { return nil }
            if ev.Op&fsnotify.Write != 0 { onChange(ev.Name) }
        case err, ok := <-w.Errors:
            if !ok { return nil }
            return err
        }
    }
}
