Implement Serialize for a wrapper type.

```rust
use serde::{Serialize, Serializer, Deserialize, Deserializer};
use std::time::Duration;

pub fn serialize_iso8601<S: Serializer>(d: &Duration, ser: S) -> Result<S::Ok, S::Error> {
    let total = d.as_secs();
    let h = total / 3600;
    let m = (total % 3600) / 60;
    let s = total % 60;
    ser.serialize_str(&format!("PT{h}H{m}M{s}S"))
}

pub fn deserialize_iso8601<'de, D: Deserializer<'de>>(de: D) -> Result<Duration, D::Error> {
    let raw = String::deserialize(de)?;
    let stripped = raw.strip_prefix("PT").ok_or_else(|| serde::de::Error::custom("missing PT"))?;
    let mut total = 0u64;
    let mut num = String::new();
    for c in stripped.chars() {
        if c.is_ascii_digit() { num.push(c); }
        else {
            let n: u64 = num.parse().map_err(serde::de::Error::custom)?;
            num.clear();
            total += match c { 'H' => n * 3600, 'M' => n * 60, 'S' => n, _ => return Err(serde::de::Error::custom("bad unit")) };
        }
    }
    Ok(Duration::from_secs(total))
}
